SELECT percentile_cont(0.25) within GROUP (ORDER BY MAX(labevents.value)) AS percentile FROM labevents JOIN patients ON labevents.subject_id = patients.subject_id JOIN icustays ON labevents.subject_id = icustays.subject_id WHERE patients.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) = 42 AND icustays.first_careunit IN ('ICU', 'CCU') AND labevents.itemid IN (SELECT itemid FROM d_labitems WHERE category = 'Vital Signs' AND label = 'Diastolic Blood Pressure') AND (labevents.value::FLOAT > 50 AND labevents.value::FLOAT < 200) AND (icustays.intime::TIME - icustays.outtime::TIME) > 120;